 for(let i=0;i<count;i++){
  if(nameAt(bytes,names+i*11)===null)return null;namesList.push(nameAt(bytes,names+i*11));
  // Preserve all native alternate frames/palettes; do not truncate Castform/Deoxys.
  const fs=lengths(front,i),bs=lengths(back,i),np=lengths(normal,i),sp=lengths(shiny,i);
  if(fs<2048||fs>8192||fs%2048||bs<2048||bs>8192||bs%2048||![32,64,96,128].includes(np)||np!==sp)return null;
  if(u16(bytes,front+i*8+4)!==2048||u16(bytes,back+i*8+4)!==2048||u16(bytes,front+i*8+6)!==i||u16(bytes,back+i*8+6)!==i||u16(bytes,normal+i*8+4)!==i||u16(bytes,shiny+i*8+4)!==500+i||u16(bytes,normal+i*8+6)!==0||u16(bytes,shiny+i*8+6)!==0)return null;
  try{for(const t of[front,back,normal,shiny])decompressSpriteLZ(bytes,ptr(bytes,t+i*8));}catch{return null;}
 }
 // Trainer sprite/palette arrays have independently verified tag runs 0..147.
 const pics=[],pals=[],trainerCount=148;
 for(let block=0;block<bytes.length;block+=0x100000){progress('Checking native trainer sprite tables…');for(let at=block;at<Math.min(block+0x100000,bytes.length-trainerCount*8);at+=4){
  if(u32(bytes,at+4)===2048&&u32(bytes,at+12)===(1<<16|2048)&&lengths(at,0)===2048&&lengths(at,1)===2048)pics.push(at);
  if(u32(bytes,at+4)===0&&u32(bytes,at+12)===1&&lengths(at,0)===32&&lengths(at,1)===32)pals.push(at);
 }await new Promise(r=>setTimeout(r,0));}
 const trainerFront=pics.filter(t=>t!==front&&t!==back&&Array.from({length:trainerCount},(_,i)=>i).every(i=>lengths(t,i)===2048&&u16(bytes,t+i*8+6)===i&&[2048,4096].includes(u16(bytes,t+i*8+4))));
 const trainerPal=pals.filter(t=>t!==normal&&t!==shiny&&Array.from({length:trainerCount},(_,i)=>i).every(i=>lengths(t,i)===32&&u32(bytes,t+i*8+4)===i));
 const profile={format:'native-frlg-sprites-1',layout:'tables',count,front,back,normal,shiny,names:namesList,speciesIds:Array.from({length:count},(_,i)=>i),blankIds:[],femaleIds:[],overworld:[],trainerCount:0};
 if(trainerFront.length===1&&trainerPal.length===1){profile.trainerFront=trainerFront[0];profile.trainerPal=trainerPal[0];profile.trainerCount=trainerCount;}
 // Icon pixels are raw 2x32x32 frames. Palettes are shared by many species.
 const icons=ptr(bytes,0x138),iconIndices=ptr(bytes,0x13c),iconPals=ptr(bytes,0x140),paletteCount=Math.max(...bytes.slice(iconIndices,iconIndices+count))+1;
 if(bounds(bytes,icons,count*4)&&bounds(bytes,iconIndices,count)&&paletteCount>=1&&paletteCount<=16&&Array.from({length:count},(_,i)=>i).every(i=>bounds(bytes,ptr(bytes,icons+i*4),1024))&&Array.from({length:paletteCount},(_,i)=>i).every(i=>bounds(bytes,ptr(bytes,iconPals+i*8),32))){profile.icons=icons;profile.iconIndices=iconIndices;profile.iconPals=iconPals;profile.iconPaletteCount=paletteCount;}
